import s from './BarberSidebar.module.css'
import Brand from './Brand'
import FindUs from './FindUs'
import SocialLinks from './SocialLinks'

export default function BarberSidebar({ data: d }) {
  const services = Array.isArray(d.services) ? d.services : []
  const gallery = Array.isArray(d.gallery) ? d.gallery : []
  const story = Array.isArray(d.story) ? d.story : []
  const phoneHref = d.PHONE_INTL
    ? 'tel:' + d.PHONE_INTL
    : d.PHONE
      ? 'tel:' + d.PHONE
      : null

  return (
    <div className={s.root}>
      <nav className={s.nav} aria-label='Κύρια πλοήγηση'>
        <div className={s.navInner}>
          <a href='#home' className={s.logo}>
            <Brand data={d} className={s.brand} dark />
          </a>
          <div className={s.navLinks}>
            <a href='#home'>Αρχική</a>
            <a href='#story'>Ιστορία</a>
            <a href='#services'>Υπηρεσίες</a>
            <a href='#pricing'>Τιμοκατάλογος</a>
            <a href='#contact'>Επικοινωνία</a>
          </div>
        </div>
      </nav>

      <main className={s.main}>
        <header id='home' className={s.hero}>
          {d.HERO_IMAGE ? <img src={d.HERO_IMAGE} alt='' className={s.heroImage} /> : null}
          <div className={s.heroOverlay} aria-hidden='true'></div>
          <div className={s.heroContent}>
            {d.KICKER ? <p className={s.kicker}>{d.KICKER}</p> : null}
            <h1 className={s.heroTitle}>{d.NAME || d.HERO_WORD}</h1>
            {d.INTRO || d.TAGLINE ? (
              <p className={s.heroTagline}>{d.INTRO || d.TAGLINE}</p>
            ) : null}
            <div className={s.heroActions}>
              <a className={s.heroButton} href='#story'>Η ιστορία μας</a>
              <a className={s.heroButtonGhost} href='#services'>Οι υπηρεσίες μας</a>
            </div>
          </div>
        </header>

        {story.length > 0 ? (
          <section id='story' className={s.section}>
            <div className={s.sectionInner}>
              <div className={s.storyGrid}>
                <div className={s.storyBody}>
                  <p className={s.eyebrow}>Η ιστορία μας</p>
                  <h2 className={s.sectionTitle}>{d.STORY_TITLE || 'Η ιστορία μας'}</h2>
                  {story.map((item, i) => (
                    <p key={i} className={s.storyParagraph}>{item.p}</p>
                  ))}
                </div>
                {d.STORY_IMAGE ? (
                  <div className={s.storyImageWrap}>
                    <img src={d.STORY_IMAGE} alt={d.STORY_TITLE || ''} className={s.storyImage} />
                  </div>
                ) : null}
              </div>
            </div>
          </section>
        ) : null}

        {gallery.length > 0 ? (
          <section id='portfolio' className={s.section}>
            <div className={s.sectionInner}>
              <p className={s.eyebrow}>Έργα</p>
              <h2 className={s.sectionTitle}>Πρόσφατα κουρέματα</h2>
              <div className={s.galleryGrid}>
                {gallery.map((item, i) => (
                  <figure className={s.galleryCard} key={i}>
                    {item.image ? <img src={item.image} alt={item.title || ''} loading='lazy' className={s.galleryImage} /> : null}
                    {item.title || item.sub ? (
                      <figcaption className={s.galleryCaption}>
                        {item.title ? <h3>{item.title}</h3> : null}
                        {item.sub ? <p>{item.sub}</p> : null}
                      </figcaption>
                    ) : null}
                  </figure>
                ))}
              </div>
            </div>
          </section>
        ) : null}

        {services.length > 0 ? (
          <section id='services' className={s.section}>
            <div className={s.sectionInner}>
              <p className={s.eyebrow}>Υπηρεσίες</p>
              <h2 className={s.sectionTitle}>Τι προσφέρουμε</h2>
              <div className={s.servicesGrid}>
                {services.map((item, i) => {
                  const media = gallery[i]
                  const image = media ? media.image : null
                  const alt = media && media.title ? media.title : item.title || ''
                  return (
                    <article className={s.serviceCard} key={i}>
                      {image ? <img src={image} alt={alt} loading='lazy' className={s.serviceImage} /> : null}
                      <div className={s.serviceInfo}>
                        <h3 className={s.serviceTitle}>{item.title}</h3>
                        {item.desc ? <p className={s.serviceDesc}>{item.desc}</p> : null}
                        {item.duration ? <span className={s.serviceDuration}>{item.duration}</span> : null}
                      </div>
                      {item.price ? <span className={s.servicePrice}>{item.price}</span> : null}
                    </article>
                  )
                })}
              </div>
            </div>
          </section>
        ) : null}

        {services.length > 0 ? (
          <section id='pricing' className={s.section}>
            <div className={s.sectionInner}>
              <div className={s.pricingHeader}>
                <div>
                  <p className={s.eyebrow}>Τιμοκατάλογος</p>
                  <h2 className={s.sectionTitle}>Η λίστα τιμών μας</h2>
                </div>
                {services[0] && services[0].price ? (
                  <strong className={s.priceStarting}>Από {services[0].price}</strong>
                ) : null}
              </div>
              <ul className={s.priceList}>
                {services.map((item, i) => (
                  <li className={s.priceItem} key={i}>
                    <span className={s.priceName}>
                      {item.title}
                      {item.duration ? <span className={s.priceDuration}> · {item.duration}</span> : null}
                    </span>
                    <span className={s.priceDivider} aria-hidden='true'></span>
                    {item.price ? <strong className={s.priceValue}>{item.price}</strong> : null}
                  </li>
                ))}
              </ul>
            </div>
          </section>
        ) : null}

        <section id='contact' className={s.section}>
          <div className={s.sectionInner}>
            <p className={s.eyebrow}>Επικοινωνία</p>
            <h2 className={s.sectionTitle}>{d.CTA_TITLE || 'Πες ένα γεια'}</h2>
            <div className={s.contactGrid}>
              <div className={s.contactInfo}>
                {d.PHONE && phoneHref ? (
                  <a className={s.contactLink} href={phoneHref}>{d.PHONE}</a>
                ) : null}
                {d.DOMAIN ? (
                  <a className={s.contactDomain} href={'https://' + d.DOMAIN} target='_blank' rel='noreferrer'>{d.DOMAIN}</a>
                ) : null}
                {d.AREAS ? <p className={s.contactArea}>{d.AREAS}</p> : null}
                {d.TRADE || d.CITY ? (
                  <p className={s.contactMeta}>
                    {d.TRADE ? <span>{d.TRADE}</span> : null}
                    {d.TRADE && d.CITY ? ' · ' : null}
                    {d.CITY ? <span>{d.CITY}</span> : null}
                    {d.POSTCODE ? <span> {d.POSTCODE}</span> : null}
                  </p>
                ) : null}
                <SocialLinks data={d} className={s.social} />
              </div>
              <div className={s.openWrap}>
                <div className={s.openCard}>
                  <h3>Ανοιχτά καθημερινά</h3>
                  {d.HOURS ? <p className={s.openHours}>{d.HOURS}</p> : null}
                </div>
              </div>
            </div>
            <div className={s.findUs}>
              <FindUs data={d} />
            </div>
          </div>
        </section>
      </main>

      <footer className={s.footer}>
        <div className={s.footerInner}>
          {d.YEAR || d.NAME ? <p>© {d.YEAR || ''} {d.NAME || ''}. Με επιφύλαξη παντός δικαιώματος.</p> : null}
          <a href='#home' className={s.backTop}>Επιστροφή στην αρχή</a>
        </div>
      </footer>
    </div>
  )
}

.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #000000;
  --vt-ink: #141414;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #141414;
  --vt-accent-ink: #141414;
  --vt-accent-on-deep: #fdbd2d;
  --vt-line: #c9c2b8;

  --font-display: 'Anton', 'Arial Narrow', Arial, sans-serif;
  --font-body: 'Fira Sans', Arial, sans-serif;

  min-height: 100vh;
  margin: 0;
  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: var(--font-body);
  line-height: 1.6;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(button) {
  font-family: inherit;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  margin: 0;
  font-family: var(--font-display);
  text-transform: uppercase;
  line-height: 1.05;
}

.root :where(img) {
  max-width: 100%;
  display: block;
}

.root :where(p) {
  margin: 0;
}

.root [id] {
  scroll-margin-top: 24px;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 3px;
}

.nav {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  z-index: 50;
  width: 300px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 32px;
  box-sizing: border-box;
}

.navInner {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.logo {
  display: block;
  margin-bottom: 72px;
}

.brand {
  text-align: center;
}

.navLinks {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  width: 100%;
}

.root .navLinks a {
  display: block;
  text-align: center;
  padding: 12px 16px;
  border-radius: 100px;
  color: var(--vt-on-accent);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.root .navLinks a:hover {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
}

.main {
  margin-left: 300px;
  min-height: 100vh;
  background: var(--vt-surface);
}

.hero {
  position: relative;
  min-height: 720px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  border-bottom: 12px solid var(--vt-accent);
  color: var(--vt-on-deep);
}

.heroImage {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: var(--vt-surface-deep);
  opacity: 0.45;
}

.heroContent {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 760px;
  padding: 64px;
}

.kicker {
  color: var(--vt-accent-on-deep);
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: 12px;
}

.heroTitle {
  color: var(--vt-on-deep);
  font-size: clamp(48px, 8vw, 96px);
  margin-bottom: 16px;
}

.heroTagline {
  color: var(--vt-on-deep);
  font-size: 20px;
  max-width: 520px;
  opacity: 0.85;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 32px;
}

.heroButton,
.heroButtonGhost {
  display: inline-block;
  border-radius: 100px;
  padding: 12px 24px;
  font-weight: 700;
  border: 2px solid var(--vt-on-deep);
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.heroButtonGhost {
  background: transparent;
  color: var(--vt-on-deep);
}

.root .heroButton:hover,
.root .heroButtonGhost:hover {
  background: var(--vt-on-deep);
  color: var(--vt-surface-deep);
}

.section {
  padding: 96px 56px;
}

.sectionInner {
  max-width: 1200px;
  margin: 0 auto;
}

.eyebrow {
  color: var(--vt-accent);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  margin-bottom: 10px;
}

.sectionTitle {
  color: var(--vt-ink);
  font-size: clamp(34px, 5vw, 58px);
  margin-bottom: 40px;
}

.storyGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.storyParagraph {
  color: var(--vt-ink-soft);
  font-size: 1.05rem;
  line-height: 1.75;
  margin-bottom: 16px;
}

.storyParagraph:last-child {
  margin-bottom: 0;
}

.storyImageWrap {
  background: var(--vt-accent);
  border-radius: 24px;
  padding: 14px;
  box-sizing: border-box;
}

.storyImage {
  width: 100%;
  height: auto;
  object-fit: cover;
  border-radius: 16px;
  transform: rotate(4deg);
}

.galleryGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.galleryCard {
  position: relative;
  margin: 0;
  border-radius: 20px;
  overflow: hidden;
  background: var(--vt-surface-2);
  aspect-ratio: 4 / 3;
}

.galleryImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.galleryCard:hover .galleryImage {
  transform: scale(1.05);
}

.galleryCaption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 32px 20px 18px;
  background: linear-gradient(180deg, transparent, var(--vt-surface-deep));
  color: var(--vt-on-deep);
}

.galleryCaption h3 {
  font-size: 22px;
  color: var(--vt-on-deep);
}

.galleryCaption p {
  color: var(--vt-on-deep);
  opacity: 0.85;
  font-size: 14px;
}

.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.serviceCard {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  background: var(--vt-surface-2);
  aspect-ratio: 4 / 3;
}

.serviceImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.serviceCard:hover .serviceImage {
  transform: scale(1.05);
}

.serviceInfo {
  position: absolute;
  inset: 16px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 20px;
  border: 1px solid var(--vt-on-deep);
  border-radius: 16px;
  box-sizing: border-box;
  background: color-mix(in srgb, var(--vt-surface-deep) 15%, transparent);
}

.serviceTitle {
  color: var(--vt-on-deep);
  font-size: 28px;
}

.serviceDesc {
  color: var(--vt-on-deep);
  font-size: 14px;
  opacity: 0.85;
  margin-top: 4px;
}

.serviceDuration {
  color: var(--vt-on-deep);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-top: 8px;
}

.servicePrice {
  position: absolute;
  top: 40px;
  right: 40px;
  z-index: 2;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 100px;
  padding: 8px 16px;
  font-weight: 700;
  font-size: 14px;
}

.pricingHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 40px;
}

.priceStarting {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 100px;
  padding: 10px 20px;
  white-space: nowrap;
}

.priceList {
  list-style: none;
}

.priceItem {
  display: flex;
  align-items: baseline;
  gap: 14px;
  padding: 16px 0;
  border-bottom: 1px solid var(--vt-line);
}

.priceItem:last-child {
  border-bottom: 0;
}

.priceName {
  font-size: 20px;
  font-weight: 700;
}

.priceDuration {
  color: var(--vt-ink-soft);
  font-size: 14px;
  font-weight: 400;
  margin-left: 4px;
}

.priceDivider {
  flex: 1;
  border-bottom: 2px dotted var(--vt-line);
  transform: translateY(-5px);
}

.priceValue {
  color: var(--vt-accent);
  font-size: 20px;
  font-weight: 700;
  white-space: nowrap;
}

.contactGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: stretch;
  margin-bottom: 48px;
}

.contactInfo {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 16px;
}

.contactLink {
  font-size: 28px;
  font-weight: 700;
  color: var(--vt-ink);
}

.root .contactLink:hover {
  color: var(--vt-accent);
}

.contactDomain {
  color: var(--vt-accent);
  font-weight: 700;
  font-size: 18px;
}

.contactArea {
  color: var(--vt-ink-soft);
  font-size: 18px;
}

.contactMeta {
  color: var(--vt-ink-soft);
}

.social {
  margin-top: 8px;
}

.openWrap {
  background: var(--vt-accent);
  border-radius: 24px;
  padding: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 220px;
  box-sizing: border-box;
}

.openCard {
  width: 100%;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  border-radius: 16px;
  padding: 36px;
  transform: rotate(3deg);
  box-sizing: border-box;
}

.openCard h3 {
  color: var(--vt-accent-on-deep);
  font-size: 24px;
  margin-bottom: 16px;
}

.openHours {
  color: var(--vt-on-deep);
  font-size: 24px;
  font-weight: 700;
}

.findUs {
  margin-top: 24px;
}

.footer {
  padding: 32px 56px;
  background: var(--vt-surface-2);
  border-top: 10px solid var(--vt-accent);
}

.footerInner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  color: var(--vt-ink-soft);
}

.backTop {
  font-weight: 700;
  color: var(--vt-ink);
}

.root .backTop:hover {
  color: var(--vt-accent);
}

@media (max-width: 991px) {
  .nav {
    position: static;
    width: auto;
    padding: 16px 24px;
    align-items: flex-start;
  }

  .navInner {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    gap: 16px;
  }

  .logo {
    margin-bottom: 0;
  }

  .navLinks {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: flex-end;
    gap: 4px;
    width: auto;
  }

  .root .navLinks a {
    padding: 8px 12px;
    font-size: 14px;
  }

  .main {
    margin-left: 0;
  }

  .section {
    padding: 64px 24px;
  }

  .hero {
    min-height: 640px;
  }

  .heroContent {
    padding: 48px 32px;
  }

  .storyGrid,
  .contactGrid {
    grid-template-columns: 1fr;
  }

  .servicesGrid,
  .galleryGrid {
    grid-template-columns: 1fr 1fr;
  }

  .footer {
    padding: 24px;
  }
}

@media (max-width: 640px) {
  .navInner {
    flex-direction: column;
    align-items: flex-start;
  }

  .navLinks {
    justify-content: flex-start;
    overflow-x: auto;
    flex-wrap: nowrap;
    width: 100%;
  }

  .root .navLinks a {
    white-space: nowrap;
  }

  .section {
    padding: 48px 20px;
  }

  .hero {
    min-height: 560px;
  }

  .heroContent {
    padding: 32px 20px;
  }

  .servicesGrid,
  .galleryGrid {
    grid-template-columns: 1fr;
  }

  .pricingHeader {
    flex-direction: column;
    align-items: flex-start;
  }

  .footerInner {
    flex-direction: column;
    align-items: flex-start;
  }
}
